def feature(ctx):
    W = ctx["WEEK"]
    ph = ctx["public_holiday"].astype(np.int8); sh = ctx["school_holiday"].astype(np.int8)
    ph_prev = np.r_[np.zeros(W, np.int8), ph[:-W]]; sh_prev = np.r_[np.zeros(W, np.int8), sh[:-W]]
    return ((ph - ph_prev) * 2 + (sh - sh_prev)).astype(np.float32)

def feature(ctx):
    f = ctx["flow"]; T, N = f.shape; W = ctx["WEEK"]
    stack = np.full((8, T, N), np.nan, dtype=np.float32)
    for k in range(1, 9):
        stack[k - 1, k * W:] = f[:-k * W]
    return np.nan_to_num(np.nanmedian(stack, axis=0)).astype(np.float32)
